WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT id, user_id, content, mastery_level, created_at, updated_at
FROM manual_knowledge
WHERE id = #{id} AND user_id = #{userId}

SELECT id, user_id, content, mastery_level, created_at, updated_at
FROM manual_knowledge
WHERE user_id = #{userId}

    AND content ILIKE #{qPattern}


    AND EXISTS (SELECT 1 FROM tags t2
                WHERE t2.manual_knowledge_id = manual_knowledge.id AND t2.name = #{tag})


    AND mastery_level = #{mastery}

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM manual_knowledge
WHERE user_id = #{userId}

    AND content ILIKE #{qPattern}


    AND EXISTS (SELECT 1 FROM tags t2
                WHERE t2.manual_knowledge_id = manual_knowledge.id AND t2.name = #{tag})


    AND mastery_level = #{mastery}
